arguments.new_str:
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Train the model before building the app
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ticket_model.zip");
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var metrics = TrainModel(dataPath, modelPath);

builder.Services.AddControllers();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.Logger.LogInformation("Micro Accuracy: {Micro:P2}", metrics.MicroAccuracy);
app.Logger.LogInformation("Macro Accuracy: {Macro:P2}", metrics.MacroAccuracy);
app.Logger.LogInformation("Log Loss:       {LogLoss:F4}", metrics.LogLoss);
app.Logger.LogInformation("Confusion Matrix:\n{Matrix}", metrics.ConfusionMatrix);

app.MapControllers();
app.MapGet("api/ticket/metrics", () => Results.Ok(metrics));

app.Run();

static ModelMetrics TrainModel(string dataPath, string modelPath)
{
    var mlContext = new MLContext(seed: 42);

    var data = mlContext.Data.LoadFromTextFile<TicketData>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    var pipeline = mlContext.Transforms.Conversion
            .MapValueToKey("Label", nameof(TicketData.Category))
        .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
        .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
        .Append(mlContext.Transforms.Concatenate("Features",
            "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
        .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
            labelColumnName: "Label", featureColumnName: "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    var model = pipeline.Fit(split.TrainSet);

    var predictions = model.Transform(split.TestSet);
    var eval = mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

    mlContext.Model.Save(model, data.Schema, modelPath);

    return new ModelMetrics
    {
        MicroAccuracy = (float)eval.MicroAccuracy,
        MacroAccuracy = (float)eval.MacroAccuracy,
        LogLoss = (float)eval.LogLoss,
        LogLossReduction = (float)eval.LogLossReduction,
        ConfusionMatrix = eval.ConfusionMatrix.GetFormattedConfusionTable()
    };
}

