[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private static readonly string[] CategoryLabels = ["Billing", "General", "Technical"];

    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;

    public TicketController(PredictionEnginePool<TicketData, TicketPrediction> predictionPool)
    {
        _predictionPool = predictionPool;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResult> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);
        var confidences = new Dictionary<string, float>();

        for (var i = 0; i < CategoryLabels.Length && i < prediction.Score.Length; i++)
        {
            confidences[CategoryLabels[i]] = prediction.Score[i];
        }

        return Ok(new TicketPredictionResult
        {
            PredictedCategory = prediction.PredictedCategory,
            ConfidenceScores = confidences
        });
    }
}

